// TestClient provides a testsuite-compatible Client
type TestAdminClient struct {
	env       *testsuite.TestWorkflowEnvironment
	workflows AdminWorkflows
}

var _ AdminClient = &TestAdminClient{}

// NewTestAdminClient initializes a new TestAdminClient value
func NewTestAdminClient(env *testsuite.TestWorkflowEnvironment, workflows AdminWorkflows, activities AdminActivities) *TestAdminClient {
	if workflows != nil {
		RegisterAdminWorkflows(env, workflows)
	}
	if activities != nil {
		RegisterAdminActivities(env, activities)
	}
	return &TestAdminClient{env, workflows}
}

// CreateNamespace executes a(n) temporal.v1.CreateNamespace workflow in the test environment
func (c *TestAdminClient) CreateNamespace(ctx context.Context, req *CreateNamespaceInput, opts ...*CreateNamespaceOptions) (*CreateNamespaceOutput, error) {
	run, err := c.CreateNamespaceAsync(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return run.Get(ctx)
}

// CreateNamespaceAsync executes a(n) temporal.v1.CreateNamespace workflow in the test environment
func (c *TestAdminClient) CreateNamespaceAsync(ctx context.Context, req *CreateNamespaceInput, options ...*CreateNamespaceOptions) (CreateNamespaceRun, error) {
	var o *CreateNamespaceOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewCreateNamespaceOptions()
	}
	opts, err := o.Build(req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing client.StartWorkflowOptions: %w", err)
	}
	return &testCreateNamespaceRun{client: c, env: c.env, opts: &opts, req: req, workflows: c.workflows}, nil
}

// GetCreateNamespace is a noop
func (c *TestAdminClient) GetCreateNamespace(ctx context.Context, workflowID string, runID string) CreateNamespaceRun {
	return &testCreateNamespaceRun{env: c.env, workflows: c.workflows}
}

// CancelWorkflow requests cancellation of an existing workflow execution
func (c *TestAdminClient) CancelWorkflow(ctx context.Context, workflowID string, runID string) error {
	c.env.CancelWorkflow()
	return nil
}

// TerminateWorkflow terminates an existing workflow execution
func (c *TestAdminClient) TerminateWorkflow(ctx context.Context, workflowID string, runID string, reason string, details ...interface{}) error {
	return c.CancelWorkflow(ctx, workflowID, runID)
}

var _ CreateNamespaceRun = &testCreateNamespaceRun{}

// testCreateNamespaceRun provides convenience methods for interacting with a(n) temporal.v1.CreateNamespace workflow in the test environment
type testCreateNamespaceRun struct {
	client    *TestAdminClient
	env       *testsuite.TestWorkflowEnvironment
	isStarted atomic.Bool
	opts      *client.StartWorkflowOptions
	req       *CreateNamespaceInput
	workflows AdminWorkflows
}

// Cancel requests cancellation of a workflow in execution, returning an error if applicable
func (r *testCreateNamespaceRun) Cancel(ctx context.Context) error {
	return r.client.CancelWorkflow(ctx, r.ID(), r.RunID())
}

// Get retrieves a test temporal.v1.CreateNamespace workflow result
func (r *testCreateNamespaceRun) Get(context.Context) (*CreateNamespaceOutput, error) {
	if r.isStarted.CompareAndSwap(false, true) {
		r.env.ExecuteWorkflow(CreateNamespaceWorkflowName, r.req)
	}
	if !r.env.IsWorkflowCompleted() {
		return nil, errors.New("workflow in progress")
	}
	if err := r.env.GetWorkflowError(); err != nil {
		return nil, err
	}
	var result CreateNamespaceOutput
	if err := r.env.GetWorkflowResult(&result); err != nil {
		return nil, err
	}
	return &result, nil
}

// ID returns a test temporal.v1.CreateNamespace workflow run's workflow ID
func (r *testCreateNamespaceRun) ID() string {
	if r.opts != nil {
		return r.opts.ID
	}
	return ""
}

// Run noop implementation
func (r *testCreateNamespaceRun) Run() client.WorkflowRun {
	return nil
}

// RunID noop implementation
func (r *testCreateNamespaceRun) RunID() string {
	return ""
}

// Terminate terminates a workflow in execution, returning an error if applicable
func (r *testCreateNamespaceRun) Terminate(ctx context.Context, reason string, details ...interface{}) error {
	return r.client.TerminateWorkflow(ctx, r.ID(), r.RunID(), reason, details...)
}
